from enum import StrEnum
class Role(StrEnum): APPLICANT='APPLICANT'; DIRECTOR='DIRECTOR'; PCC_ADMIN='PCC_ADMIN'; ATTORNEY='ATTORNEY'; SYSTEM='SYSTEM'
class ApplicationStatus(StrEnum):
 DRAFT='DRAFT'; SUBMITTED='SUBMITTED'; RESUBMITTED='RESUBMITTED'; UNDER_REVIEW='UNDER_REVIEW'; NEEDS_REVISION='NEEDS_REVISION'; REJECTED='REJECTED'; APPROVED='APPROVED'; WITHDRAWN='WITHDRAWN'; FILED='FILED'; GRANTED='GRANTED'; CLOSED='CLOSED'; EXPIRED='EXPIRED'; APPEAL_SUBMITTED='APPEAL_SUBMITTED'; DECISION_MODIFIED='DECISION_MODIFIED'; REJECTION_UPHELD='REJECTION_UPHELD'; REMANDED_FOR_AMENDMENT='REMANDED_FOR_AMENDMENT'
class AttorneyState(StrEnum): NONE='NONE'; OFFERED='OFFERED'; DECLINED='DECLINED'; ASSIGNED='ASSIGNED'
class BudgetOutcome(StrEnum): NONE='NONE'; APPROVED='APPROVED'; REJECTED='REJECTED'; ESCALATED='ESCALATED'; ESCALATION_TRACKED='ESCALATION_TRACKED'
class MaintenanceState(StrEnum): DUE='DUE'; RENEWED='RENEWED'; NOT_RENEWED='NOT_RENEWED'; COMPLETED='COMPLETED'; DO_NOT_RENEW='DO_NOT_RENEW'; MAINTENANCE_ACTIVE='MAINTENANCE_ACTIVE'; RENEWAL_APPROVED='RENEWAL_APPROVED'; RENEWAL_DECISION_REQUESTED='RENEWAL_DECISION_REQUESTED'
class OfficeActionState(StrEnum): RECEIVED='RECEIVED'; RESPONSE_DRAFT='RESPONSE_DRAFT'; APPLICANT_APPROVAL='APPLICANT_APPROVAL'; REVIEW='REVIEW'; SUBMITTED='SUBMITTED'; CLOSED='CLOSED'; EXTENSION_REQUESTED='EXTENSION_REQUESTED'; NONE='NONE'; APPLICANT_APPROVED='APPLICANT_APPROVED'; AWAITING_APPLICANT_APPROVAL='AWAITING_APPLICANT_APPROVAL'; OFFICE_ACTION_RECORDED='OFFICE_ACTION_RECORDED'; RESPONSE_READY='RESPONSE_READY'; RESPONSE_SUBMITTED='RESPONSE_SUBMITTED'
class AppealOutcome(StrEnum): UPHELD='UPHELD'; REVERSED='REVERSED'; REMANDED='REMANDED'
class FilingType(StrEnum): NATIONAL='National'; INTERNATIONAL='International'
class Recommendation(StrEnum): FILE_PATENT='File Patent'; DO_NOT_FILE='Do Not File'; NEEDS_AMENDMENT='Needs Amendment'
class ReviewDecision(StrEnum): APPROVED='APPROVED'; REJECTED='REJECTED'; NEEDS_REVISION='NEEDS_REVISION'
def display_state(state, attorney_state=None):
 base=state.value.replace('_',' ').title() if hasattr(state,'value') else str(state).replace('_',' ').title()
 if state==ApplicationStatus.APPROVED and attorney_state is not None:
  return {AttorneyState.OFFERED:"Assignment Offered",AttorneyState.ASSIGNED:"Attorney Assigned",AttorneyState.DECLINED:"Pending Review",AttorneyState.NONE:"Approved"}.get(attorney_state,base)
 return base
